import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

// Story F5 — Input, checked in the source.
//
// TextInput paints only through the redesign's tokens: no literal colors,
// no old color or type tokens, no ring and no radius. Its old box/underline
// variants are gone from every call site; sign-in uses the large size and
// the two dialogs pass their names as labels. The rendered look is checked
// in the browser by e2e/inputs.spec.ts.
// Do not edit this file to match an implementation.

const SRC = fileURLToPath(new URL('../../', import.meta.url));

function source(path: string) {
  return readFileSync(join(SRC, path), 'utf8');
}

function withoutComments(code: string) {
  return code.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
}

function tsxFiles(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return tsxFiles(path);
    return name.endsWith('.tsx') ? [path] : [];
  });
}

/** Every `<TextInput … />` opening tag in a file, whitespace collapsed. */
function textInputTags(code: string) {
  return Array.from(code.matchAll(/<TextInput\b[\s\S]*?\/>/g), (m) => m[0].replace(/\s+/g, ' '));
}

const OLD_COLOR_TOKENS = [
  'background',
  'foreground',
  'ink-2',
  'ink-3',
  'rule',
  'rule-strong',
  'hover-tint',
  'panel-tint',
  'accent',
  'accent-hover',
  'ok-tint',
  'required',
  'recommended',
  'incomplete',
];

describe('F5 Input source', () => {
  it('TextInput uses only the redesign tokens: no literal color, old token, ring or radius', () => {
    const code = withoutComments(source('components/ui/TextInput.tsx'));

    expect(code).not.toMatch(/#[0-9a-f]{3,8}\b/i);
    expect(code).not.toMatch(/\b(rgb|rgba|hsl|hsla|oklch)\(/);
    expect(code).not.toMatch(/\b(text|bg|border)-(white|black)\b/);
    expect(code).not.toMatch(/\brounded\b|\brounded-/);
    expect(code).not.toMatch(/\bring-/);
    expect(code).not.toMatch(/\bfont-display\b|\btext-(headline|body|help)(?![\w-])/);
    expect(code).not.toMatch(/\[font-weight:/);
    for (const name of OLD_COLOR_TOKENS) {
      expect(code, name).not.toMatch(new RegExp(`(?:^|[\\s'"\`:])(?:text|bg|border)-${name}(?![\\w-])`));
    }
    for (const utility of [
      'border-line-muted',
      'focus:border-line-highlight',
      'border-error',
      'text-error',
      'text-primary',
      'placeholder:text-muted',
      'text-body-normal',
      'text-body-large',
      'text-title-4',
    ]) {
      expect(code, utility).toContain(utility);
    }
  });

  it('no call site passes the old variant prop', () => {
    const offenders: string[] = [];
    for (const file of tsxFiles(SRC)) {
      const code = withoutComments(readFileSync(file, 'utf8'));
      for (const tag of textInputTags(code)) {
        if (/\bvariant=/.test(tag)) offenders.push(`${file.slice(SRC.length)}: ${tag}`);
      }
    }
    expect(offenders).toEqual([]);
  });

  it('sign-in is large and the two dialogs pass their names as labels', () => {
    const signIn = textInputTags(withoutComments(source('components/auth/SignInForm.tsx')));
    const newPuzzle = textInputTags(withoutComments(source('components/puzzle/NewPuzzleDialog.tsx')));
    const builderName = textInputTags(withoutComments(source('components/puzzle/DisplayNameDialog.tsx')));

    expect(signIn).toHaveLength(1);
    expect(signIn[0]).toMatch(/\bsize="large"/);
    expect(newPuzzle).toHaveLength(1);
    expect(newPuzzle[0]).toMatch(/\blabel="Puzzle name"/);
    expect(builderName).toHaveLength(1);
    expect(builderName[0]).toMatch(/\blabel="Builder name"/);
  });
});
